int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t; 

    while (t--) {
        int N;
        cin >> N;

        vector<int> P(N + 1), pos(N + 1);
        for (int i = 1; i <= N; i++) {
            cin >> P[i];
            pos[P[i]] = i; 
        }

        vector<int> D(N + 1);
        for (int i = 1; i <= N; i++) cin >> D[i];

        vector<int> ord(N);

        bool ok = true;

        for (int val = N; val >= 1 && ok; --val) {
            int i = pos[val];

            int m = 0;
            for (int idx : ord) if (idx > i) ++m;

            if (D[i] > m) {
                ok = false;
                break;
            }

            int needBefore = m - D[i]; 
            int cnt = 0;
            int insertPos = 0;

            while (insertPos < (int)ord.size() && cnt < needBefore) {
                if (ord[insertPos] > i) ++cnt;
                ++insertPos;
            }

            ord.insert(ord.begin() + insertPos, i);
        }

        if (!ok) {
            cout << -1 << '\n';
            continue;
        }

        vector<int> A(N + 1, 0);
        for (int k = 0; k < N; k++) {
            A[ord[k]] = k + 1;
        }

        for (int i = 1; i <= N; i++) {
            cout << A[i] << (i == N ? '\n' : ' ');
        }
    }

    return 0;
}

